        "uv_tool_version": "0.8.4",
        "dependency_installation": "uv sync --all-groups --all-extras",
        "pytest_usage": [
          "uv run pytest -vv --splits 8 --group <group_number> --durations=10 --maxfail=3"
        ],
        "test_dirs": ["lib/crewai", "lib/crewai-tools"],
        "tests_split_parallel": true,
        "job_timeout_minutes": 15,
        "no_reference_to_missing_test_file": true
      }
